    async Select3RandomNameCheckboxInGrid(): Promise<void> {
        const rowCount = await this.grid.getRowCount(this.uIResultTable);
        const indices = new Set<number>();
        while (indices.size < 3 && indices.size < rowCount) {
            indices.add(Math.floor(Math.random() * rowCount));
        }
        for (const idx of indices) {
            await this.grid.selectRowCheckboxByIndex(this.uIResultTable, idx);
        }
    }

    async Select6RandomNameCheckboxInGrid(): Promise<void> {
        const rowCount = await this.grid.getRowCount(this.uIResultTable);
        const indices = new Set<number>();
        while (indices.size < 6 && indices.size < rowCount) {
            indices.add(Math.floor(Math.random() * rowCount));
        }
        for (const idx of indices) {
            await this.grid.selectRowCheckboxByIndex(this.uIResultTable, idx);
        }
    }

    async select6RandomNameCheckboxesInGrid(): Promise<void> {
        const rowCount = await this.grid.getRowCount(this.uIResultTable);
        if (rowCount === 0) return;
        let selectedCount = 0;
        const triedIndexes = new Set<number>();
        while (selectedCount < 6 && triedIndexes.size < rowCount) {
            const randomIndex = Math.floor(Math.random() * rowCount);
            if (triedIndexes.has(randomIndex)) continue;
            triedIndexes.add(randomIndex);
            const row = this.uIResultTable.locator('tbody tr').nth(randomIndex);
            const checkbox = row.locator('img').first();
            const title = await checkbox.getAttribute('title') || '';
            if (title.toLowerCase() !== 'checked') {
                await checkbox.scrollIntoViewIfNeeded();
                await checkbox.click();
                selectedCount++;
            }
        }
    }

