    async mouserHoverAtNameAndVerifyActivities(): Promise<void> {
        const cell = await this.grid.getGridCell(this.uIResultTable, BaseData.getNamesModuleValue('Name'), 'Name');
        await cell.hover();
        await this.page.waitForTimeout(1000);
        const cells = this.uINameActivityMouseover.locator('tbody tr td');
        const cellCount = await cells.count();
        const actualValues: string[] = [];
        for (let i = 0; i < cellCount; i++) {
            const text = (await cells.nth(i).innerText()).trim();
            if (text !== '') {
                actualValues.push(text);
            }
        }
        const expectedValues = [
            BaseData.getNamesModuleValue('Date'),
            BaseData.getNamesModuleValue('Activity'),
            BaseData.getNamesModuleValue('Date'),
            BaseData.getNamesModuleValue('Activity1'),
            BaseData.getNamesModuleValue('Date'),
            BaseData.getNamesModuleValue('Activity2')
        ];
        expect(actualValues).toEqual(expectedValues);
    }

