    async getAllColumnValuesAcrossPages(colName: string): Promise<string[]> {
        const allValues: string[] = [];
        while (true) {
            const rowCount = await this.grid.getRowCount(this.uIResultTable);
            for (let i = 0; i < rowCount; i++) {
                const cellText = await this.grid.getGridCellInnerText(this.uIResultTable, colName, i);
                if (cellText && cellText.trim() !== '') {
                    allValues.push(cellText.trim());
                }
            }
            if (await this.uINextLink.count() === 0 || !(await this.uINextLink.isVisible())) {
                break;
            }
            await this.uINextLink.click();
            await this.page.waitForLoadState('load');
            await this.page.waitForTimeout(1000);
        }
        return allValues;
    }

