    async verifyNameTypeInGridByAtIdType(nameIDTypeJsonKeyIndex: number): Promise<void> {

        // 1. Retrieve the expected prefix from your test data
        const expectedPrefix = BaseData.getNamesModuleValue(`NameIDType${nameIDTypeJsonKeyIndex}`);

        // 2. Extract all values from the 'ID' column across all pages
        const allIdValues = await this.grid.getAllColumnValuesAcrossPages(
            this.page,
            this.uIResultTable,
            'ID',
            this.uINextButton
        );

        // 3. Prevent false positives: Ensure we actually extracted data
        expect(
            allIdValues.length,
            'Expected to find records in the grid, but the grid was empty.'
        ).toBeGreaterThan(0);

        // 4. Iterate and verify each ID
        for (const actualId of allIdValues) {
            // Use the length of expectedPrefix instead of a hardcoded '1'. 
            // This makes the method future-proof if the prefix ever becomes 'AA' or 'XYZ'.
            const actualPrefix = actualId.substring(0, expectedPrefix.length);

            expect(
                actualPrefix,
                `Row Verification Failed -> The ID '${actualId}' does not start with expected prefix '${expectedPrefix}'`
            ).toBe(expectedPrefix);
        }
    }


