    async verifyAtChargeByActivityTypeInReport(pdfdata: string): Promise<void> {
        const lines = pdfdata.split('\n');
        for (const line of lines) {
            if (line.includes(BaseData.getNamesModuleValue('ActivityType'))) {
                const parts = line.split(/\s+/);
                const chargeBuilder: string[] = [];
                for (let i = 3; i < parts.length; i++) {
                    if (parts[i] === BaseData.getNamesModuleValue('ActivityType')) break;
                    chargeBuilder.push(parts[i]);
                }
                const charge = chargeBuilder.join(' ');
                expect(charge).toBe(BaseData.getNamesModuleValue('Charge'));
            }
        }
    }

