    async EnterAdultDOB(): Promise<void> {
        const day = String(Math.floor(Math.random() * 26) + 1).padStart(2, '0');
        const month = String(Math.floor(Math.random() * 12) + 1).padStart(2, '0');
        const yearsBack = Math.floor(Math.random() * (60 - 19 + 1)) + 20;
        const year = new Date().getFullYear() - yearsBack;
        const randomAdultDOB = `${month}${day}${year}`;
        await this.uIDOBEdit.click();
        await this.uIDOBEdit.fill(randomAdultDOB);
        await this.uIDOBEdit.press('Tab');
    }

    async EnterAtOutRangeDOB(): Promise<void> {
        await this.uIDOBEdit.click();
        await this.uIDOBEdit.fill(BaseData.getNamesModuleValue('DOB'));
        await this.uIDOBEdit.press('Tab');
    }

    async EnterFutureDOB(): Promise<void> {
        await this.uIDOBEdit.click();
        const future = new Date();
        future.setFullYear(future.getFullYear() + 5);
        const mm = String(future.getMonth() + 1).padStart(2, '0');
        const dd = String(future.getDate()).padStart(2, '0');
        const yyyy = future.getFullYear();
        await this.uIDOBEdit.fill(`${mm}${dd}${yyyy}`);
        await this.uIDOBEdit.press('Tab');
    }

