    async EnterDOBAsAdultForCurrentDate(): Promise<void> {
        const DOB = await this.uIDOBEdit.inputValue();
        const Age = await this.uIAgeTextView.inputValue();
        const DOBYear = parseInt(DOB.substring(6));
        const currentAge = parseInt(Age);
        const AdultAgeDiff = 18 - currentAge;
        const AdultAge = DOBYear - AdultAgeDiff;
        const now = new Date();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        const dd = String(now.getDate()).padStart(2, '0');
        await this.uIDOB.clear();
        await this.uIDOB.fill(`${mm}/${dd}/${AdultAge}`);
        await this.uIDOB.press('Tab');
    }

    async verifyAsAdultAgeByYear(): Promise<void> {
        const dob = BaseData.getNamesModuleValue("DOB");
        const parts = dob.split('/');
        const birthDate = new Date(parseInt(parts[2]), parseInt(parts[0]) - 1, parseInt(parts[1]));
        const today = new Date();
        let age = today.getFullYear() - birthDate.getFullYear();
        const monthDiff = today.getMonth() - birthDate.getMonth();
        if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birthDate.getDate())) {
            age--;
        }
        const actualAge = await this.uIAgeTextView.inputValue();
        expect(actualAge).toBe(String(age));
    }

