    async doubleClickOnAllColumns(): Promise<void> {
        const rows = this.uIEmpSchoolGridTable.locator('tr');
        const rowCount = await rows.count();
        for (let i = 0; i < rowCount; i++) {
            const row = rows.nth(i);
            const rowClass = await row.getAttribute('class') || '';
            if (rowClass.includes('igg_BlueThemeActiveRow')) {
                const cells = row.locator('td');
                const cellCount = await cells.count();
                for (let j = 0; j < cellCount; j++) {
                    const cell = cells.nth(j);
                    if (await cell.isVisible()) {
                        await cell.dblclick();
                        await cell.pressSequentially('12345');
                        const text = await cell.innerText();
                        expect(text).not.toContain('12345');
                    }
                }
                break;
            }
        }
    }

    async selectAtNameInGrid(): Promise<void> {
        await this.grid.selectRowByCellText(this.uIEmpSchoolGridTable, BaseData.getNamesModuleValue('Name'));
    }

