export class NameEntryHistoryTabPage {
    readonly page: Page;
    readonly grid: GridHelpers;
    readonly uIScreenViewRadioButton: Locator;
    readonly uIDateViewRadioButton: Locator;
    readonly uIHistoryResultGrid: Locator;
    readonly uIExpandRowButton: Locator;
    readonly uICollapseRowButton: Locator;
    readonly uIExpandRow1Button: Locator;
    readonly uIHistoryPhoneResultGrid: Locator;
    readonly uINameCreatedText: Locator;
    readonly uINameModifiedText: Locator;
    readonly uINameCreatedDetails: Locator;
    readonly uILastActivityOn: Locator;

    constructor(page: Page) {
        this.page = page;
        this.grid = new GridHelpers(page);
        this.uIScreenViewRadioButton = page.locator('#rdbScreenView');
        this.uIDateViewRadioButton = page.locator('#rdbDateView');
        this.uIHistoryResultGrid = page.locator('#grdHistory_ctl00');
        this.uIExpandRowButton = page.locator("//img[@title = 'Expand Row']");
        this.uICollapseRowButton = page.locator("//img[@title = 'Collapse Row']");
        this.uIExpandRow1Button = page.locator("//div[@id='grdHistory_ctl00']//img[@un = '1']");
        this.uIHistoryPhoneResultGrid = page.locator('#grdHistory_ctl00_Phones_0');
        this.uINameCreatedText = page.locator('#lblCreateDetails');
        this.uINameModifiedText = page.locator('#lblModDetails1');
        this.uINameCreatedDetails = page.locator('#lblCreateDetails');
        this.uILastActivityOn = page.locator("//span[contains(@id,'lbllastActivityDetails1')]");
    }

    async ClickDateViewRadioButton(): Promise<void> {
        await this.uIDateViewRadioButton.click();
    }

    async ClickExpandIcon(): Promise<void> {
        await this.uIExpandRowButton.click();
        await this.page.waitForTimeout(1000);
    }

    async ClickExpandIcon1Row(): Promise<void> {
        await this.uIExpandRow1Button.click();
        await this.page.waitForTimeout(1000);
    }

    async VerifyDateAsCurrentDate(rowIndex: number): Promise<void> {
        const today = new Date();
        const formatted = `${String(today.getMonth() + 1).padStart(2, '0')}/${String(today.getDate()).padStart(2, '0')}/${today.getFullYear()}`;
        const text = await this.grid.getGridCellInnerText(this.uIHistoryPhoneResultGrid, 'Date', rowIndex);
        expect(text).toContain(formatted);
    }

    async VerifyKeyValueAsAddedPhone(rowIndex: number): Promise<void> {
        const text = await this.grid.getGridCellInnerText(this.uIHistoryPhoneResultGrid, 'Key Value', rowIndex);
        expect(text).toContain('Added Header Phone Number');
    }

    async VerifyKeyValueAsAddedTabPhone(rowIndex: number): Promise<void> {
        const text = await this.grid.getGridCellInnerText(this.uIHistoryPhoneResultGrid, 'Key Value', rowIndex);
        expect(text).toContain('Tab Phone Number');
    }

    async verifyAtScreenNameInGrid(): Promise<void> {
        const element = this.page.locator(`//td[text()='${BaseData.getNamesModuleValue('ScreeName')}']`);
        await element.scrollIntoViewIfNeeded();
        const text = await element.innerText();
        expect(text).toBe(BaseData.getNamesModuleValue('ScreeName'));
    }

    async verifyAtNameCreated(Count: number): Promise<void> {
        const text = await this.uINameCreatedText.innerText();
        expect(text).toBe(BaseData.getNamesModuleValue('Created' + Count));
    }

    async verifyAtNameModified(): Promise<void> {
        const today = new Date();
        const formatted = `${String(today.getMonth() + 1).padStart(2, '0')}/${String(today.getDate()).padStart(2, '0')}/${String(today.getFullYear()).substring(2)}`;
        const modified = BaseData.getNamesModuleValue('Modified') + ' ' + formatted + ' by ' + BaseData.getNamesModuleValue('PF');
        const text = await this.uINameModifiedText.innerText();
        expect(text).toBe(modified);
    }

    async verifyAtNameCreatedCurrentDate(): Promise<void> {
        const today = new Date();
        const formatted = `${String(today.getMonth() + 1).padStart(2, '0')}/${String(today.getDate()).padStart(2, '0')}/${String(today.getFullYear()).substring(2)}`;
        const created = BaseData.getNamesModuleValue('Created1') + ' ' + formatted + ' by ' + BaseData.getNamesModuleValue('PF1');
        const text = await this.uINameCreatedText.innerText();
        expect(text).toBe(created);
    }

    async VerifyNameCreatedDateAndOfficer(): Promise<void> {
        const currentDate = DateHelpers.getCurrentDate();
        const dateFormat = currentDate.substring(0, 6) + currentDate.substring(8, 10);
        await this.page.waitForTimeout(1000);
        const createdTxt = await this.uINameCreatedDetails.innerText();
        expect(createdTxt).toContain(BaseData.getNamesModuleValue('Officer'));
        expect(createdTxt).toContain(dateFormat);
        expect(createdTxt).toContain(BaseData.getNamesModuleValue('PF'));
    }

    async verifyAtScreenName(): Promise<void> {
        const tableText = await this.uIHistoryResultGrid.innerText();
        expect(tableText).toContain(BaseData.getNamesModuleValue('ScreeName'));
    }

    async verifyAtKeyValueInAliasGrid(ExpandRowName: string, ContainValue: string, count: number): Promise<void> {
        await this.uIHistoryResultGrid.locator(`//tr//td[text()='${ExpandRowName}']/..//td//img`).click();
        const value = await this.page.locator(`//div[contains(@id,'grdHistory_ctl00_${ExpandRowName}')]//td[contains(text(),'${ContainValue}')]`).innerText();
        expect(value).toBe(BaseData.getNamesModuleValue('KeyValue' + count));
    }

    async verifyScrollBarPresent(): Promise<void> {
        const hasScrollbar = await this.page.evaluate(() => document.documentElement.scrollHeight > document.documentElement.clientHeight);
        expect(hasScrollbar).toBe(true);
    }

    async verifyAtLastActivityOn(): Promise<void> {
        const text = await this.uILastActivityOn.innerText();
        expect(text).toBe(BaseData.getNamesModuleValue('LastActivityOn'));
    }

    async getLastActivityOn(): Promise<string> {
        const lastActivity = await this.uILastActivityOn.innerText();
        const regex = /\b(\d{2}\/\d{2}\/\d{2,4}|\d{4}[-\/]\d{2}[-\/]\d{2})\b/;
        const match = lastActivity.match(regex);
        return match ? match[1] : '';
    }

    async verifyLastActivityOn(lastActivityOn: string): Promise<void> {
        const lastActivity = await this.uILastActivityOn.innerText();
        const regex = /\b(\d{2}\/\d{2}\/\d{2,4}|\d{4}[-\/]\d{2}[-\/]\d{2})\b/;
        const match = lastActivity.match(regex);
        const extracted = match ? match[1] : '';
        expect(extracted).toBe(lastActivityOn);
    }

}

