    async setCaseYearToJSONFile(testCaseId: string): Promise<void> {
        const caseYear = (await this.uIArrestYearEdit.inputValue()).substring(0, 2);
        const fs = require('fs');
        const path = require('path');
        const filePath = path.resolve('test-data/Names.json');
        const data = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
        if (data[testCaseId]) { data[testCaseId].caseYear = caseYear; }
        fs.writeFileSync(filePath, JSON.stringify(data, null, 2), 'utf-8');
    }

    async setCaseNumberToJSONFile(testCaseId: string): Promise<void> {
        const caseNo = (await this.uIArrestNumberEdit.inputValue()).substring(0, 6);
        const fs = require('fs');
        const path = require('path');
        const filePath = path.resolve('test-data/Names.json');
        const data = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
        if (data[testCaseId]) { data[testCaseId].caseNo = caseNo; }
        fs.writeFileSync(filePath, JSON.stringify(data, null, 2), 'utf-8');
    }

