    async getBookingFieldValueInReportByAtArrestNoUsingIndex(pdfText: string, i: number): Promise<string> {
        try {
            const fieldName = eval(`FieldName${i}`);
            const bookingDataMap: Record<string, Record<string, string>> = {};

            pdfText = pdfText.replace(/(?:\s*\n\s*)/g, ' ').replace(/\s{2,}/g, ' ').trim();
            pdfText = pdfText.replace(/ProPhoenix rev\..*|\*\* Confidential.*/gi, '').trim();

            const pattern = /(\d{2}-\d{6})\s+(\d{2}\/\d{2}\/\d{4})\s+(\d{2}:\d{2})\s+(\d{2}-\d{6})\s+(.+?)\s+(\S+,\s+\S)\s+(\S+)\s+(Male|Female)\s+([A-Za-z\-]+(?:\s+[A-Za-z\-]+){0,2})/g;
            let match;

            while ((match = pattern.exec(pdfText)) !== null) {
                const record: Record<string, string> = {};
                record['Booking#'] = match[1];
                record['ArrestDate'] = match[2];
                record['Time'] = match[3];
                record['CaseNo'] = match[4];
                record['ArrestLocation'] = match[5].trim();
                record['Name'] = match[6].trim();
                record['Charge'] = match[7].trim();
                record['Sex'] = match[8].trim();
                record['Race'] = match[9].trim();
                bookingDataMap[match[1]] = record;
            }

            const arrestNo = ArrestNo;
            if (bookingDataMap[arrestNo]) {
                const booking = bookingDataMap[arrestNo];
                if (booking[fieldName]) {
                    return booking[fieldName];
                }
            }
        } catch (e) {
            // Exception in getBookingField
        }
        return '';
    }

