    async verifyAtBusinessName(rowIndex: number): Promise<void> {
        const expected = rowIndex === 0 ? BusinessName : eval(`BusinessName${rowIndex}`);
        const cells = this.uIEmpSchoolGridTable.locator(`tr:nth-child(${rowIndex === 0 ? 1 : rowIndex}) td`);
        const count = await cells.count();
        let found = false;
        for (let i = 0; i < count; i++) {
            const text = await cells.nth(i).innerText();
            if (text.includes(expected)) {
                expect(text).toContain(expected);
                found = true;
                break;
            }
        }
        expect(found).toBeTruthy();
    }

