    async verifyDateRangeInDateColumn(): Promise<void> {
        const columnValues = await this.grid.getGridTableColumnValues(this.uIResultTable, 'Date');
        const fromDate = await this.uIDateFromEdit.inputValue();
        const toDate = await this.uIToDateEdit.inputValue();
        for (const dateValue of columnValues) {
            const trimmed = dateValue.trim();
            if (trimmed) {
                expect(new Date(trimmed).getTime()).toBeGreaterThanOrEqual(new Date(fromDate).getTime());
                expect(new Date(trimmed).getTime()).toBeLessThanOrEqual(new Date(toDate).getTime());
            }
        }
    }

