    async switchToPseudonymEntry(): Promise<void> {
        await this.page.waitForTimeout(3000);
        let pages = this.page.context().pages();
        const mainPage = pages.find(p => p.url().toLowerCase().includes('loader'));
        let targetPage = pages.filter(p => p !== mainPage && !p.isClosed() && p.url().toLowerCase().includes('pseudonym')).pop()
            || pages.filter(p => p !== mainPage && !p.isClosed()).pop();
        if (!targetPage) {
            try {
                targetPage = await this.page.context().waitForEvent('page', { timeout: 15000 });
                await targetPage.waitForLoadState('load');
            } catch {
                pages = this.page.context().pages();
                targetPage = pages.filter(p => p !== mainPage && !p.isClosed()).pop();
            }
        }
        if (targetPage) {
            try { await targetPage.bringToFront(); } catch { }
            (this.page as any).__lastSwitchedPopup = targetPage;
        } else {
            try {
                await this.browserHelpers.switchToPageByTitle('Pseudonym Entry');
            } catch { /* ignore */ }
        }
    }

